// Generated central VNDRLY/U catalog. No company records or assignments.
import {gunzipSync} from 'node:zlib';
export type CatalogCourse={id:string;title:string;lessons:{id:string;title:string;body:string}[]};
export type CatalogProgram={id:string;title:string;equivalentCertification:string|null;courseIds:string[]};
export const vndrlyUCatalog: {programs:CatalogProgram[];courses:CatalogCourse[]}=JSON.parse(gunzipSync(Buffer.from('','base64')).toString('utf8'));
